import { BankStatementParseError } from '../bank-import.types';

import { attributeOf, child, children, decodeXmlEntities, parseXml, textAt } from './safe-xml';

describe('safe-xml', () => {
  const document = `<?xml version="1.0" encoding="UTF-8"?>
<!-- generated by bank -->
<ns:Document xmlns:ns="urn:iso:std:iso:20022:tech:xsd:camt.053.001.02" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
  <ns:Stmt>
    <ns:Id>STMT-1</ns:Id>
    <ns:Ntry><ns:Amt Ccy="EUR">10.00</ns:Amt><ns:AddtlNtryInf>M&amp;M &lt;GmbH&gt; &#228;&#x00FC;</ns:AddtlNtryInf></ns:Ntry>
    <ns:Ntry><ns:Amt Ccy='CHF'>2.50</ns:Amt><ns:AddtlNtryInf><![CDATA[<raw> & text]]></ns:AddtlNtryInf></ns:Ntry>
    <ns:Empty/>
  </ns:Stmt>
</ns:Document>`;

  it('parses elements, strips prefixes and resolves namespaces', () => {
    const root = parseXml(document);

    expect(root.name).toBe('Document');
    expect(root.namespace).toBe('urn:iso:std:iso:20022:tech:xsd:camt.053.001.02');
    expect(child(root, 'Stmt')?.namespace).toBe('urn:iso:std:iso:20022:tech:xsd:camt.053.001.02');
    expect(textAt(root, 'Stmt', 'Id')).toBe('STMT-1');
    expect(children(child(root, 'Stmt'), 'Ntry')).toHaveLength(2);
    expect(child(root, 'Stmt', 'Empty')?.children).toEqual([]);
    expect(textAt(root, 'Stmt', 'Empty')).toBeUndefined();
    expect(textAt(root, 'Stmt', 'Missing', 'Deeper')).toBeUndefined();
  });

  it('decodes predefined entities, character references, CDATA and attributes', () => {
    const root = parseXml(document);
    const [first, second] = children(child(root, 'Stmt'), 'Ntry');

    expect(textAt(first, 'AddtlNtryInf')).toBe('M&M <GmbH> äü');
    expect(textAt(second, 'AddtlNtryInf')).toBe('<raw> & text');
    expect(attributeOf(child(first, 'Amt'), 'Ccy')).toBe('EUR');
    expect(attributeOf(child(second, 'Amt'), 'Ccy')).toBe('CHF');
    expect(attributeOf(child(second, 'Amt'), 'toString')).toBeUndefined();
  });

  it('resolves a default namespace inherited by children', () => {
    const root = parseXml('<Document xmlns="urn:x"><A><B>1</B></A></Document>');

    expect(child(root, 'A', 'B')?.namespace).toBe('urn:x');
  });

  it('rejects DOCTYPE declarations (XXE)', () => {
    const xxe = `<?xml version="1.0"?>
<!DOCTYPE foo [ <!ENTITY xxe SYSTEM "file:///etc/passwd"> ]>
<Document><Id>&xxe;</Id></Document>`;

    expect(() => parseXml(xxe)).toThrow(BankStatementParseError);
    expect(() => parseXml(xxe)).toThrow(/not allowed/);
  });

  it('rejects billion-laughs entity expansion', () => {
    const laughs = `<?xml version="1.0"?>
<!DOCTYPE lolz [
 <!ENTITY lol "lol">
 <!ENTITY lol2 "&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;">
 <!ENTITY lol3 "&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;">
]>
<lolz>&lol3;</lolz>`;

    expect(() => parseXml(laughs)).toThrow(BankStatementParseError);
  });

  it('rejects lower-case or spaced doctype variants and stray ENTITY declarations', () => {
    expect(() => parseXml('<!doctype x><x/>')).toThrow(BankStatementParseError);
    expect(() => parseXml('<x><!ENTITY a "b"></x>')).toThrow(BankStatementParseError);
    expect(() => parseXml('<x><![INCLUDE[ y ]]></x>')).toThrow(BankStatementParseError);
  });

  it('rejects undefined entity references', () => {
    expect(() => parseXml('<x>&nbsp;</x>')).toThrow(/Undefined entity/);
    expect(() => parseXml('<x a="&foo;"/>')).toThrow(/Undefined entity/);
    expect(() => parseXml('<x>a & b</x>')).toThrow(BankStatementParseError);
    expect(() => parseXml('<x>&#0;</x>')).toThrow(/invalid character/);
  });

  it('enforces the depth limit', () => {
    const deep = `${'<a>'.repeat(70)}${'</a>'.repeat(70)}`;

    expect(() => parseXml(deep)).toThrow(/nested too deeply/);
    expect(parseXml(`${'<a>'.repeat(64)}${'</a>'.repeat(64)}`).name).toBe('a');
  });

  it('handles very deep documents iteratively within a raised limit', () => {
    const depth = 20_000;
    const root = parseXml(`${'<a>'.repeat(depth)}x${'</a>'.repeat(depth)}`, { maxDepth: depth });

    expect(root.name).toBe('a');
  });

  it('enforces element count and input size limits', () => {
    expect(() => parseXml(`<r>${'<e/>'.repeat(11)}</r>`, { maxElements: 10 })).toThrow(/too many elements/);
    expect(() => parseXml('<r>0123456789</r>', { maxInputLength: 10 })).toThrow(/maximum size/);
  });

  it('rejects prototype-polluting attribute names', () => {
    expect(() => parseXml('<x __proto__="1"/>')).toThrow(/Forbidden attribute/);
    expect(() => parseXml('<x p:constructor="1"/>')).toThrow(/Forbidden attribute/);
    expect(() => parseXml('<x xmlns:prototype="urn:a"/>')).toThrow(BankStatementParseError);

    const root = parseXml('<x a="1"/>');

    expect(Object.getPrototypeOf(root.attributes)).toBeNull();
  });

  it('rejects malformed documents', () => {
    expect(() => parseXml('<a><b></a></b>')).toThrow(/Unexpected end tag/);
    expect(() => parseXml('<a>')).toThrow(/Unclosed element/);
    expect(() => parseXml('<a/><b/>')).toThrow(/more than one root/);
    expect(() => parseXml('text<a/>')).toThrow(/outside of the root/);
    expect(() => parseXml('')).toThrow(/no root element/);
    expect(() => parseXml('<a x=1/>')).toThrow(/quoted/);
    expect(() => parseXml('<a x="1"y="2"/>')).toThrow(/separated/);
    expect(() => parseXml('<a x="1" x="2"/>')).toThrow(/Duplicate attribute/);
    expect(() => parseXml('<a><!-- unterminated </a>')).toThrow(/Unterminated comment/);
  });

  it('reports the line of an error', () => {
    expect(() => parseXml('<a>\n<b>\n</c>\n</a>')).toThrow(/line 3/);
  });

  it('decodes entity strings standalone', () => {
    expect(decodeXmlEntities('a &quot;b&quot; &apos;c&apos; &#x1F600;')).toBe('a "b" \'c\' 😀');
    expect(decodeXmlEntities('plain')).toBe('plain');
  });
});
